msaBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "msaBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "MokkenLab",
                name = "msa",
                version = c(1,0,0),
                options = options,
                results = msaResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'none')
        }))

#' Mokken Scale Analysis
#'
#' Scalability coefficients of a set of items (item pairs, items and the whole 
#' scale) with standard errors, confidence intervals and tests against a lower 
#' bound, by group, with reliability, Guttman-error outliers, bounds for 
#' dichotomous items, norm statistics and plain-language interpretation.
#' 
#' @param data .
#' @param vars .
#' @param groupVar .
#' @param clusterVar .
#' @param showKeySummary .
#' @param showChoicesGuide .
#' @param showGuides .
#' @param showRepro .
#' @param naHandling .
#' @param twowaySets .
#' @param twowaySeed .
#' @param scoreRange .
#' @param scoreMin .
#' @param scoreMax .
#' @param negItems .
#' @param se .
#' @param ci .
#' @param ciWidth .
#' @param typeCI .
#' @param showHij .
#' @param showZ .
#' @param zLowerbound .
#' @param typeZ .
#' @param showReliability .
#' @param relMS .
#' @param relAlpha .
#' @param relLambda2 .
#' @param relLCRC .
#' @param lcrcClassesMode .
#' @param lcrcClasses .
#' @param relIRC .
#' @param showErrors .
#' @param errorsGplus .
#' @param errorsOplus .
#' @param errorsPlot .
#' @param showBounds .
#' @param boundsQuant .
#' @param boundsLower .
#' @param boundsUpper .
#' @param showNorms .
#' @param normsZ .
#' @param normsStanines .
#' @param normsPercentiles .
#' @param hiPlot .
#' @param hijPlot .
#' @param groupPlot .
#' @param normsPlot .
#' @param plotWidth .
#' @param plotHeight .
#' @param plotPointSize .
#' @param plotLineWidth .
#' @param plotNcol .
#' @param plotLegend .
#' @param plotAxisAngle .
#' @param plotYRange .
#' @param plotValueLabels .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$cacheStore} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$intro} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$keySummary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$choicesGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$scaleGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$scale} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$items} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$hijGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$hij} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$completedSets} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$groups} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$groupItems} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$reliabilityGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$reliability} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$irc} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$errorsGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$errors} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$errorsPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$gplusOV} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$oplusOV} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$boundsGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$bounds} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$normsGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$normsSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$normsZ} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$normsSta9} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$normsPerc} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$hiPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$hijPlotImg} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$groupPlotImg} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$normsPlotImg} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$interpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$reproducibility} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$reproducibilityCode} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
msa <- function(
    data,
    vars,
    groupVar = NULL,
    clusterVar = NULL,
    showKeySummary = TRUE,
    showChoicesGuide = FALSE,
    showGuides = FALSE,
    showRepro = TRUE,
    naHandling = "listwise",
    twowaySets = 1,
    twowaySeed = 2026,
    scoreRange = "observed",
    scoreMin = 0,
    scoreMax = 4,
    negItems = list(),
    se = TRUE,
    ci = TRUE,
    ciWidth = 95,
    typeCI = "WB",
    showHij = FALSE,
    showZ = TRUE,
    zLowerbound = 0.3,
    typeZ = "WB",
    showReliability = TRUE,
    relMS = TRUE,
    relAlpha = TRUE,
    relLambda2 = TRUE,
    relLCRC = FALSE,
    lcrcClassesMode = "auto",
    lcrcClasses = 3,
    relIRC = FALSE,
    showErrors = FALSE,
    errorsGplus = TRUE,
    errorsOplus = FALSE,
    errorsPlot = FALSE,
    showBounds = FALSE,
    boundsQuant = 0.9,
    boundsLower = TRUE,
    boundsUpper = FALSE,
    showNorms = FALSE,
    normsZ = TRUE,
    normsStanines = TRUE,
    normsPercentiles = TRUE,
    hiPlot = TRUE,
    hijPlot = FALSE,
    groupPlot = TRUE,
    normsPlot = FALSE,
    plotWidth = 0,
    plotHeight = 0,
    plotPointSize = 2,
    plotLineWidth = 0.8,
    plotNcol = 0,
    plotLegend = "bottom",
    plotAxisAngle = "a45",
    plotYRange = "full",
    plotValueLabels = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("msa requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if ( ! missing(groupVar)) groupVar <- jmvcore::resolveQuo(jmvcore::enquo(groupVar))
    if ( ! missing(clusterVar)) clusterVar <- jmvcore::resolveQuo(jmvcore::enquo(clusterVar))
    if ( ! missing(negItems)) negItems <- jmvcore::resolveQuo(jmvcore::enquo(negItems))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL),
            `if`( ! missing(groupVar), groupVar, NULL),
            `if`( ! missing(clusterVar), clusterVar, NULL),
            `if`( ! missing(negItems), negItems, NULL))


    options <- msaOptions$new(
        vars = vars,
        groupVar = groupVar,
        clusterVar = clusterVar,
        showKeySummary = showKeySummary,
        showChoicesGuide = showChoicesGuide,
        showGuides = showGuides,
        showRepro = showRepro,
        naHandling = naHandling,
        twowaySets = twowaySets,
        twowaySeed = twowaySeed,
        scoreRange = scoreRange,
        scoreMin = scoreMin,
        scoreMax = scoreMax,
        negItems = negItems,
        se = se,
        ci = ci,
        ciWidth = ciWidth,
        typeCI = typeCI,
        showHij = showHij,
        showZ = showZ,
        zLowerbound = zLowerbound,
        typeZ = typeZ,
        showReliability = showReliability,
        relMS = relMS,
        relAlpha = relAlpha,
        relLambda2 = relLambda2,
        relLCRC = relLCRC,
        lcrcClassesMode = lcrcClassesMode,
        lcrcClasses = lcrcClasses,
        relIRC = relIRC,
        showErrors = showErrors,
        errorsGplus = errorsGplus,
        errorsOplus = errorsOplus,
        errorsPlot = errorsPlot,
        showBounds = showBounds,
        boundsQuant = boundsQuant,
        boundsLower = boundsLower,
        boundsUpper = boundsUpper,
        showNorms = showNorms,
        normsZ = normsZ,
        normsStanines = normsStanines,
        normsPercentiles = normsPercentiles,
        hiPlot = hiPlot,
        hijPlot = hijPlot,
        groupPlot = groupPlot,
        normsPlot = normsPlot,
        plotWidth = plotWidth,
        plotHeight = plotHeight,
        plotPointSize = plotPointSize,
        plotLineWidth = plotLineWidth,
        plotNcol = plotNcol,
        plotLegend = plotLegend,
        plotAxisAngle = plotAxisAngle,
        plotYRange = plotYRange,
        plotValueLabels = plotValueLabels)

    analysis <- msaClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

